{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Plecanatide, a large peptide, showed negligible systemic availability in humans after oral dosing, directly supporting low oral bioavailability for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Hexarelin, a peptide, had oral bioavailability of 0.3 ± 0.1% in humans, supporting low F for peptide drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "CGP 38 560, a peptidomimetic renin inhibitor, had <1% oral bioavailability in humans at 200 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Octreotide, a cyclic octapeptide, had absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Sampatrilat, a peptide-like dual inhibitor, had approximately 2% systemic bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "GHRP-6, a hexapeptide, had ~0.3% oral systemic availability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, had 0.5% oral bioavailability in humans at 40 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Remikiren, a peptidomimetic renin inhibitor, had 0.3% oral bioavailability in humans at 1600 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Polymyxin B, a cyclic peptide, is not used orally due to poor bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Three renin inhibitors (RO 425892, CGP 38560, A-64662) were <2% bioavailable in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Paliperidone ER had 28% absolute oral bioavailability in humans, but it is a small non-peptide molecule with very low transferability to this query; this is the only contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a very large, highly polar peptide-like conjugate with extreme MW, TPSA, HBD/HBA, and rotatable bond counts. All relevant human oral bioavailability data for peptide and peptidomimetic drugs—plecanatide, octreotide, GHRP-6, hexarelin, renin inhibitors, polymyxin B, and sampatrilat—show F <2%, mostly <1%. The only high-F analogue (paliperidone, 28%) is a small non-peptide molecule with negligible transferability. Therefore, F >=20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "Fasted-state-specific data are not explicitly reported for most analogues, though oral dosing in fasted conditions is typical.",
    "The query contains PEG and fatty-acid moieties not present in the closest peptide analogues; their effect on permeability is not directly covered by the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

